20	// 比较两个浮点数数组是否近似相等（允许 1e-6 相对误差）
21	static bool approx_equal(const float *x, const float *y) {
22	    for (int i = 0; i < VECTOR_SIZE; ++i) {
23	        float diff = fabsf(x[i] - y[i]);
24	        float tol = 1e-6f * fmaxf(fabsf(x[i]), fabsf(y[i]));
25	        if (diff > tol && diff > 1e-7f) {
26	            return false;
27	        }
28	    }
29	    return true;
30	}
