31	static int mesh_upi_avx512_symm_int_init(struct test *test) {
32	    if (sysconf(_SC_NPROCESSORS_ONLN) < 2) {
33	        return -255;   // 需要至少 2 个线程
34	    }
35	
36	    auto *td = new TestData;
37	    if (!td) return EXIT_FAILURE;
38	
39	    td->data = (int32_t*)aligned_alloc(16, TOTAL_BYTES);
40	    if (!td->data) {
41	        delete td;
42	        return EXIT_FAILURE;
43	    }
44	    memset(td->data, 0, TOTAL_BYTES);
45	
46	    td->next_block.store(0, std::memory_order_relaxed);
47	    td->global_sum.store(0, std::memory_order_relaxed);
48	    td->write_done.store(0, std::memory_order_relaxed);
49	    td->read_done.store(0, std::memory_order_relaxed);
50	    td->reset_lock.store(0, std::memory_order_relaxed);
51	    td->thread_idx.store(0, std::memory_order_relaxed);
52	    td->total_threads = sysconf(_SC_NPROCESSORS_ONLN);
53	    test->data = td;
54	
55	    return EXIT_SUCCESS;
56	}
57	
58	static int mesh_upi_avx512_symm_int_run(struct test *test, int cpu) {
59	    (void)cpu;
60	    auto *td = static_cast<TestData*>(test->data);
61	
62	    int id = td->thread_idx.fetch_add(1, std::memory_order_relaxed);
63	    uint32_t total = td->total_threads;
64	
65	    std::mt19937 rng(std::random_device{}());
66	    std::uniform_int_distribution<int32_t> dist(-1000000, 1000000);
67	
68	    #define GREEN "\033[32m"
69	    #define RED   "\033[31m"
70	    #define RESET "\033[0m"
71	
72	    do {
73	        // ---------- 写阶段：分配块并写入 ----------
74	        while (true) {
75	            uint32_t block = td->next_block.fetch_add(1, std::memory_order_seq_cst);
76	            if (block >= NUM_BLOCKS) break;
77	
78	            size_t offset = block * BLOCK_SIZE;
79	            int32_t vals[BLOCK_SIZE];
80	            uint64_t local_sum = 0;
81	            for (int j = 0; j < BLOCK_SIZE; ++j) {
82	                vals[j] = dist(rng);
83	                local_sum += (uint64_t)vals[j];
84	            }
85	            // 使用 4 个 NEON 向量存储 16 个元素
86	            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
87	                int32x4_t vec = vld1q_s32(vals + v * NEON_VECTOR_SIZE);
88	                vst1q_s32(td->data + offset + v * NEON_VECTOR_SIZE, vec);
89	            }
90	            __sync_synchronize();   // 类似 _mm_sfence
91	
92	            td->global_sum.fetch_add(local_sum, std::memory_order_seq_cst);
93	            td->write_done.fetch_add(1, std::memory_order_seq_cst);
94	        }
95	
96	        // 等待所有块写完成
97	        while (td->write_done.load(std::memory_order_seq_cst) < NUM_BLOCKS &&
98	               test_time_condition(test)) {
99	            __asm__ volatile("yield");
100	        }
101	        if (!test_time_condition(test)) break;
102	
103	        // ---------- 读阶段：读取整个数组并校验 ----------
104	        uint64_t read_sum = 0;
105	        bool consistent = true;
106	        alignas(16) int32_t store_buf[BLOCK_SIZE];   // 用于一致性测试
107	
108	        for (size_t i = 0; i < TOTAL_ELEMENTS; i += BLOCK_SIZE) {
109	            // 加载 16 个元素
110	            int32_t vals[BLOCK_SIZE];
111	            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
112	                int32x4_t vec = vld1q_s32(td->data + i + v * NEON_VECTOR_SIZE);
113	                vst1q_s32(vals + v * NEON_VECTOR_SIZE, vec);
114	            }
115	            for (int j = 0; j < BLOCK_SIZE; ++j) {
116	                read_sum += (uint64_t)vals[j];
117	            }
118	
119	            // 一致性测试：Store/Load 比较
120	            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
121	                int32x4_t orig = vld1q_s32(vals + v * NEON_VECTOR_SIZE);
122	                vst1q_s32(store_buf + v * NEON_VECTOR_SIZE, orig);
123	            }
124	            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
125	                int32x4_t orig = vld1q_s32(vals + v * NEON_VECTOR_SIZE);
126	                int32x4_t reload = vld1q_s32(store_buf + v * NEON_VECTOR_SIZE);
127	                uint32x4_t cmp = vceqq_s32(orig, reload);
128	                if (!(vgetq_lane_u32(cmp, 0) == 0xFFFFFFFF &&
129	                      vgetq_lane_u32(cmp, 1) == 0xFFFFFFFF &&
130	                      vgetq_lane_u32(cmp, 2) == 0xFFFFFFFF &&
131	                      vgetq_lane_u32(cmp, 3) == 0xFFFFFFFF)) {
132	                    consistent = false;
133	                    break;
134	                }
135	            }
136	            if (!consistent) break;
137	        }
138	
139	        uint64_t expected_sum = td->global_sum.load(std::memory_order_seq_cst);
140	        bool sum_ok = (read_sum == expected_sum);
141	        bool passed = sum_ok && consistent;
142	
143	        // 输出结果（仅由线程 0 输出，避免重复）
144	        if (id == 0) {
145	            fprintf(stderr, "mesh_upi_avx512_symm_int: Thread %d, data[0..15]=(%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d), read_sum=%lu, expected_sum=%lu, consistent=%d, result=%s%s%s\n",
146	                    id,
147	                    td->data[0], td->data[1], td->data[2], td->data[3],
148	                    td->data[4], td->data[5], td->data[6], td->data[7],
149	                    td->data[8], td->data[9], td->data[10], td->data[11],
150	                    td->data[12], td->data[13], td->data[14], td->data[15],
151	                    read_sum, expected_sum, consistent,
152	                    passed ? GREEN : RED,
153	                    passed ? "PASS" : "FAIL",
154	                    RESET);
155	            fflush(stderr);
156	        }
157	
158	        if (!passed) {
159	            report_fail_msg("mesh_upi_avx512_symm_int: Sum mismatch or consistency failure");
160	            return EXIT_FAILURE;
161	        }
162	
163	        // 注册读完成
164	        td->read_done.fetch_add(1, std::memory_order_seq_cst);
165	
166	        // ---------- 重置阶段（由最后一个读完成的线程执行） ----------
167	        uint32_t expected_lock = 0;
168	        if (td->reset_lock.compare_exchange_strong(expected_lock, 1,
169	                                                   std::memory_order_seq_cst,
170	                                                   std::memory_order_seq_cst)) {
171	            // 等待所有线程完成读取
172	            while (td->read_done.load(std::memory_order_seq_cst) < total &&
173	                   test_time_condition(test)) {
174	                __asm__ volatile("yield");
175	            }
176	            if (!test_time_condition(test)) {
177	                td->reset_lock.store(0, std::memory_order_seq_cst);
178	                break;
179	            }
180	
181	            // 重置共享状态
182	            td->global_sum.store(0, std::memory_order_seq_cst);
183	            td->next_block.store(0, std::memory_order_seq_cst);
184	            td->write_done.store(0, std::memory_order_seq_cst);
185	            td->read_done.store(0, std::memory_order_seq_cst);
186	            td->reset_lock.store(0, std::memory_order_seq_cst);
187	        } else {
188	            // 未获得锁，等待重置完成（即 reset_lock 变为 0）
189	            while (td->reset_lock.load(std::memory_order_seq_cst) != 0 &&
190	                   test_time_condition(test)) {
191	                __asm__ volatile("yield");
192	            }
193	            if (!test_time_condition(test)) break;
194	        }
195	
196	    } while (test_time_condition(test));
197	
198	    return EXIT_SUCCESS;
199	
200	    #undef GREEN
201	    #undef RED
202	    #undef RESET
203	}
