74	    const size_t lanes = d->vl_d;
75	    const svbool_t pg = svptrue_b64();
76	    const svfloat64_t one_half = svdup_f64(1.5);
77	    for (size_t off = 0; off < n; off += lanes) {
78	        svuint64_t vidx = svld1_u64(pg, &d->gather_idx[off]);
79	        svfloat64_t v = svld1_gather_u64index_f64(
80	            pg, reinterpret_cast<const double *>(d->gather_src.data()), vidx);
81	        v = svmla_f64_x(pg, one_half, v, v);
82	        svst1_scatter_u64index_f64(
83	            pg, reinterpret_cast<double *>(d->scatter_dst.data()), vidx, v);
84	    }
