/**
 * @copyright
 * Copyright 2026.
 * SPDX-License-Identifier: Apache-2.0
 *
 * @test @b power_virus_dit_sve_arm
 * @parblock
 * Full-width SVE di/dt voltage-transient power virus — the SVE port of
 * power_virus_dit (NEON128). At a 512-bit vector length the same burst
 * drives 4x the datapath width: larger transient current swings and 4x
 * the per-cycle bit-toggle density in the bypass network — the physical
 * mechanism behind SEVI (ASPLOS'26) Obs.4 (wider vectors carry
 * additional low-frequency SDC cases: more transistors active + 2x power
 * causing voltage-margin excursions).
 *
 * Structure per cycle (power_virus_dit skeleton, widened):
 *   BURST: a dependent svmla_f64_x chain at full runtime VL, operands
 *          alternating between two high-Hamming-distance f64 patterns
 *          every step (max multiplier-input toggling). Every 64 steps
 *          the burst performs an svld1_f64 load with the base pointer
 *          re-read from a stack slot — address generation inside the
 *          burst current window (the NUMA3 fault's address-path x
 *          burst compound). No time check inside the burst.
 *   STALL: yield-hint loop draining the vector units (unchanged from
 *          the NEON version).
 *
 * SDC detection: each burst's final accumulator is compared byte-exact
 * against a scalar fma reference repeating the identical dependent
 * sequence (the load contribution is folded into the chain: every 64th
 * step's multiplier operand comes from the loaded vector, mirrored in
 * the golden in the same order).
 *
 * Cross-core barrier: NOT used — the framework has no barrier helper
 * (known gap), so cores burst on statistically-random phases; cluster
 * saturation comes from the framework's one-thread-per-CPU execution
 * itself (design tradeoff recorded here; lockstep would be an
 * enhancement, not a requirement — the NEON version ships the same
 * way).
 *
 * test_init probes HWCAP_SVE and returns a clean EXIT_SKIP on SVE-less
 * CPUs. Any runtime vector length (full 512-bit on 0xd22). Built in
 * tests_arm64_sve.
 * @endparblock
 */

#include <sandstone.h>
#include <cstdint>
#include <cinttypes>
#include <cstring>
#include <cmath>

#ifdef __aarch64__
#include <sys/auxv.h>
#include <asm/hwcap.h>
#include <arm_sve.h>
#endif

// Burst/stall sizes (matched duty cycle, power_virus_dit precedent).
static constexpr int BURST_INNER = 2048;
static constexpr int STALL_INNER = 2048;

// Load-in-burst period: base pointer re-read from a stack slot and used
// for an SVE load every LOAD_PERIOD steps of the burst.
static constexpr int LOAD_PERIOD = 64;

#ifdef __aarch64__

// High-Hamming alternating operand pairs (|x| <= 2, exact).
static constexpr double A0 = 1.3333333333333333;   // 0x3FF5555555555555
static constexpr double A1 = -1.6666666666666667;  // 0xBFFAAAAAAAAAAAAA
static constexpr double B0 = 0.3333333333333333;   // 0x3FD5555555555555
static constexpr double B1 = -0.8333333333333333;  // 0xBFEAAAAAAAAAAAAA

static int power_virus_dit_sve_arm_init(struct test *test)
{
    unsigned long hwcap = getauxval(AT_HWCAP);
    if ((hwcap & HWCAP_SVE) == 0) {
        log_skip(CpuNotSupportedSkipCategory,
                 "ARM64 SVE not available; power_virus_dit_sve_arm "
                 "requires SVE (full-width di/dt burst)");
        return EXIT_SKIP;
    }
    (void)test;
    return EXIT_SUCCESS;
}

static inline void stall_yield(int n)
{
    for (int i = 0; i < n; ++i)
        __asm__ volatile("yield" ::: "memory");
}

static int power_virus_dit_sve_arm_run(struct test *test, int cpu)
{
    (void)cpu;
    const size_t vl_d = svcntd();
    const svbool_t pg = svptrue_b64();

    // Load-in-burst operands (address-generation x burst compound).
    std::vector<double> loadbuf(vl_d * 4);
    for (size_t i = 0; i < loadbuf.size(); ++i)
        loadbuf[i] = (i & 1) ? B0 : B1;
    // Stack slot holding the base pointer — re-read every LOAD_PERIOD.
    const double *base_slot = loadbuf.data();
    size_t load_idx = 0;

    // Scalar golden: identical dependent sequence, lane 0's view (all
    // lanes run the same values; the vector accumulator is lane-uniform
    // because every operand vector is a splat or the loadbuf pattern
    // whose lane 0 is B1). Mirror exactly: acc = fma(acc_op, m_k, a_k)
    // with the per-step (m,a) alternating and every LOAD_PERIOD-th step
    // taking m from loadbuf[lane0 of the loaded vector].
    auto golden_burst = [&](double acc0) -> double {
        double acc = acc0;
        for (int k = 0; k < BURST_INNER; ++k) {
            double m = (k & 1) ? A1 : A0;
            double a = (k & 1) ? B1 : B0;
            if (k % LOAD_PERIOD == 0) {
                // loaded vector lane 0 (loadbuf pattern: even idx B1)
                m = loadbuf[(load_idx * vl_d) % loadbuf.size()];
                ++load_idx;
            }
            // svmla_f64_x(pg, acc, m, a): acc = acc + m*a ... NOTE the
            // intrinsic arg order: svmla(pg, op1, op2, op3) = op1 + op2*op3
            acc = std::fma(m, a, acc);
        }
        return acc;
    };

    // lane-uniform check: the loaded vector is NOT uniform (even/odd
    // lanes differ). Only lane 0 is golden-checked per burst; the other
    // lanes use the same chain with their own loaded values — full-lane
    // golden below keeps it exact.
    std::vector<double> golden(vl_d);
    {
        size_t li = 0;
        for (size_t lane = 0; lane < vl_d; ++lane) {
            double acc = 0.0;
            for (int k = 0; k < BURST_INNER; ++k) {
                double m = (k & 1) ? A1 : A0;
                double a = (k & 1) ? B1 : B0;
                if (k % LOAD_PERIOD == 0) {
                    m = loadbuf[(li * vl_d + lane) % loadbuf.size()];
                }
                acc = std::fma(m, a, acc);
            }
            golden[lane] = acc;
        }
        (void)li;
    }

    do {
        bool all_passed = true;
        for (int cycle = 0; cycle < 8; ++cycle) {
            // ---- BURST: dependent full-width SVE FMA chain with
            // alternating operands and periodic stack-reload loads ----
            load_idx = 0;
            svfloat64_t acc = svdup_f64(0.0);
            svfloat64_t a0v = svdup_f64(A0);
            svfloat64_t a1v = svdup_f64(A1);
            svfloat64_t b0v = svdup_f64(B0);
            svfloat64_t b1v = svdup_f64(B1);
            for (int k = 0; k < BURST_INNER; ++k) {
                if (k % LOAD_PERIOD == 0) {
                    // base pointer re-read from the stack slot — the
                    // address-generation op inside the burst window
                    const double *b = base_slot;
                    size_t off = (load_idx * vl_d) % loadbuf.size();
                    svfloat64_t lv = svld1_f64(pg, b + off);
                    acc = svmla_f64_x(pg, acc, lv, (k & 1) ? b1v : b0v);
                    ++load_idx;
                } else if (k & 1) {
                    acc = svmla_f64_x(pg, acc, a1v, b1v);
                } else {
                    acc = svmla_f64_x(pg, acc, a0v, b0v);
                }
            }
            std::vector<double> hw(vl_d);
            svst1_f64(pg, hw.data(), acc);
            for (size_t lane = 0; lane < vl_d; ++lane) {
                if (hw[lane] != golden[lane]) {
                    uint64_t g, a;
                    memcpy(&g, &golden[lane], 8);
                    memcpy(&a, &hw[lane], 8);
                    log_warning("power_virus_dit_sve: burst %d lane %zu "
                                "golden=0x%016" PRIx64 " actual=0x%016"
                                PRIx64, cycle, lane, g, a);
                    all_passed = false;
                }
            }
            if (!all_passed)
                break;

            // ---- STALL ----
            stall_yield(STALL_INNER);
        }

        if (!all_passed) {
            report_fail_msg("power_virus_dit_sve_arm: di/dt transient SDC "
                            "detected (SVE FMA corrupted mid burst/stall)");
            return EXIT_FAILURE;
        }
    } while (test_time_condition(test));

    return EXIT_SUCCESS;
}

#else

static int power_virus_dit_sve_arm_init(struct test *test)
{
    (void)test;
    return EXIT_SUCCESS;
}
static int power_virus_dit_sve_arm_run(struct test *test, int cpu)
{
    (void)test;
    (void)cpu;
    log_skip(CpuNotSupportedSkipCategory,
             "to be implemented (placeholder): ARM SVE required for the "
             "SVE di/dt power virus");
    return EXIT_SKIP;
}

#endif

static int power_virus_dit_sve_arm_cleanup(struct test *test)
{
    (void)test;
    return EXIT_SUCCESS;
}

DECLARE_TEST(power_virus_dit_sve_arm,
             "Full-width SVE di/dt voltage-transient power virus: dependent "
             "svmla_f64_x burst chains with alternating high-Hamming "
             "operands and periodic stack-reload SVE loads (address "
             "generation inside the burst window), alternating with yield "
             "stalls — the SVE-512 port of power_virus_dit, byte-exact vs "
             "a per-lane scalar fma golden")
    .groups = DECLARE_TEST_GROUPS(&group_math),
    .test_init = power_virus_dit_sve_arm_init,
    .test_run = power_virus_dit_sve_arm_run,
    .test_cleanup = power_virus_dit_sve_arm_cleanup,
    .quality_level = TEST_QUALITY_PROD,
END_DECLARE_TEST

/**
 * @copyright
 * Copyright 2026.
 * SPDX-License-Identifier: Apache-2.0
 *
 * @test @b mesh_upi_avx512_symm_f64
 * @parblock
 * Cross-core shared-data f64 production/consumption SDC stress — the
 * first floating-point variant in the mesh family (all 27 existing mesh
 * tests are int32). The known NUMA3 fault class is a compound of
 * remote/shared access x compute; until now the suite covered the two
 * halves separately (mesh_int: shared access, integer; sve512_*: FP
 * compute, private data). This test combines them on the mesh_upi
 * three-phase skeleton (write / read-verify / reset with atomic block
 * claiming), with FP compute on both sides of the shared buffer:
 *
 *   WRITE phase: each claimed block is produced with a 4-step NEON
 *     vfmaq_f64 local chain over exact binary values, then stored.
 *
 *   READ phase: every element of the shared buffer is loaded, run
 *     through the same 4-step FMA chain, and byte-compared against the
 *     recomputed golden; plus the store/reload consistency check of the
 *     original skeleton.
 *
 *   Global sum: per-block sums (computed exactly on both sides — block
 *     values are 0.5-multiples, so every chain result and every sum is
 *     exact in f64, order-independent) are accumulated into atomic
 *     f64 counters on each side; read total must equal write total
 *     byte-for-byte. Exactness argument: with all values being exact
 *     halves and bounded magnitude, no rounding ever occurs, so the
 *     floating-point associativity hazard does not exist here.
 *
 * NEON f64 (float64x2_t) — runs on any aarch64, no SVE needed, so the
 * compound coverage also exists on SVE-less hosts (this Kunpeng 920
 * included, where it is fully verified on real hardware).
 * @endparblock
 */

#include <sandstone.h>
#include <cstdint>
#include <cstring>
#include <atomic>
#ifdef __aarch64__
#include <arm_neon.h>
#include <unistd.h>
#include <cstdlib>
#include <sys/sysinfo.h>

#define NEON_VECTOR_SIZE 2                // NEON 一次处理 2 个 f64
#define BLOCK_SIZE 16                     // 逻辑块大小(8 个 float64x2)
#define VECTORS_PER_BLOCK (BLOCK_SIZE / NEON_VECTOR_SIZE)  // = 8
#define NUM_BLOCKS 64
#define TOTAL_ELEMENTS (BLOCK_SIZE * NUM_BLOCKS)  // = 1024
#define TOTAL_BYTES (TOTAL_ELEMENTS * sizeof(double))

struct TestData {
    alignas(16) double *data;             // 共享缓冲(16B 对齐)
    std::atomic<uint32_t> next_block;
    std::atomic<uint64_t> global_sum;     // f64 位模式的精确和(见下)
    std::atomic<uint32_t> write_done;
    std::atomic<uint32_t> read_done;
    std::atomic<uint32_t> reset_lock;
    std::atomic<uint32_t> thread_idx;
    uint32_t total_threads;
};

// 块值生成:slot j 的种子值(精确 0.5 倍数)
static inline double block_value(uint32_t block, int j)
{
    // 范围 [0.5, 16.0) 的精确值:0.5 * (1..32)
    return 0.5 * (double)(1 + ((block * 16 + (uint32_t)j) % 32));
}

// 4 步 NEON FMA 链(精确:值域内每步结果都是 0.5 倍数,无舍入)
static inline double fma_chain(double v)
{
    float64x2_t acc = vdupq_n_f64(v);
    float64x2_t m = vdupq_n_f64(0.5);
    float64x2_t a = vdupq_n_f64(0.5);
    acc = vfmaq_f64(acc, m, a);   // v + 0.25
    acc = vfmaq_f64(acc, m, a);   // v + 0.50
    acc = vfmaq_f64(acc, m, a);   // v + 0.75
    acc = vfmaq_f64(acc, m, a);   // v + 1.00
    return vgetq_lane_f64(acc, 0);
}

// 标量 golden:与 NEON 链完全同序同值(每步 +0.25,精确)
static inline double fma_chain_scalar(double v)
{
    return v + 0.25 + 0.25 + 0.25 + 0.25;
}

static int mesh_upi_avx512_symm_f64_init(struct test *test) {
    if (sysconf(_SC_NPROCESSORS_ONLN) < 2)
        return -255;   // 需要至少 2 个线程

    auto *td = new TestData;
    if (!td) return EXIT_FAILURE;

    td->data = (double *)aligned_alloc(16, TOTAL_BYTES);
    if (!td->data) {
        delete td;
        return EXIT_FAILURE;
    }
    memset(td->data, 0, TOTAL_BYTES);

    td->next_block.store(0, std::memory_order_relaxed);
    td->global_sum.store(0, std::memory_order_relaxed);
    td->write_done.store(0, std::memory_order_relaxed);
    td->read_done.store(0, std::memory_order_relaxed);
    td->reset_lock.store(0, std::memory_order_relaxed);
    td->thread_idx.store(0, std::memory_order_relaxed);
    td->total_threads = sysconf(_SC_NPROCESSORS_ONLN);
    test->data = td;

    return EXIT_SUCCESS;
}

static int mesh_upi_avx512_symm_f64_run(struct test *test, int cpu) {
    (void)cpu;
    auto *td = static_cast<TestData *>(test->data);

    int id = td->thread_idx.fetch_add(1, std::memory_order_relaxed);
    uint32_t total = td->total_threads;

    do {
        // ---------- 写阶段:认领块,FP 生产,NEON 存储 ----------
        uint64_t local_sum_bits = 0;   // 精确和以位模式累加? 不 —— 用 double
        double local_sum = 0.0;
        while (true) {
            uint32_t block = td->next_block.fetch_add(1, std::memory_order_seq_cst);
            if (block >= NUM_BLOCKS) break;

            size_t offset = block * BLOCK_SIZE;
            double vals[BLOCK_SIZE];
            for (int j = 0; j < BLOCK_SIZE; ++j) {
                vals[j] = block_value(block, j);
                local_sum += vals[j];   // 精确:0.5 倍数求和无舍入
            }
            // NEON 存储(每块 8 个 float64x2)
            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
                float64x2_t vec = vld1q_f64(vals + v * NEON_VECTOR_SIZE);
                vst1q_f64(td->data + offset + v * NEON_VECTOR_SIZE, vec);
            }
            __sync_synchronize();

            td->write_done.fetch_add(1, std::memory_order_seq_cst);
        }
        (void)local_sum_bits;

        // 写侧全局和:local_sum 精确,fetch_add 顺序无关
        // (double 的原子 fetch_add 不存在;用 CAS 循环)
        double expected = td->global_sum.load(std::memory_order_seq_cst);
        double sum_snapshot;
        do {
            sum_snapshot = expected;
            double desired = sum_snapshot + local_sum;   // 精确加法
            uint64_t des_bits, exp_bits;
            memcpy(&des_bits, &desired, 8);
            memcpy(&exp_bits, &sum_snapshot, 8);
            uint64_t old = td->global_sum.compare_exchange_weak(
                exp_bits, des_bits, std::memory_order_seq_cst,
                std::memory_order_seq_cst);
            if (old == exp_bits) break;
            memcpy(&expected, &old, 8);
        } while (true);

        // 等待所有块写完成
        while (td->write_done.load(std::memory_order_seq_cst) < NUM_BLOCKS &&
               test_time_condition(test)) {
            __asm__ volatile("yield");
        }
        if (!test_time_condition(test)) break;

        // ---------- 读阶段:全量读 + FMA 链 + golden 比对 ----------
        double read_sum = 0.0;
        bool consistent = true;
        alignas(16) double store_buf[BLOCK_SIZE];

        for (size_t i = 0; i < TOTAL_ELEMENTS; i += BLOCK_SIZE) {
            double vals[BLOCK_SIZE];
            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
                float64x2_t vec = vld1q_f64(td->data + i + v * NEON_VECTOR_SIZE);
                vst1q_f64(vals + v * NEON_VECTOR_SIZE, vec);
            }
            for (int j = 0; j < BLOCK_SIZE; ++j) {
                read_sum += vals[j];            // 精确
                double got = fma_chain(vals[j]);
                double want = fma_chain_scalar(vals[j]);
                if (got != want) {              // byte-exact(精确值,== 可靠)
                    consistent = false;
                    break;
                }
            }
            if (!consistent) break;

            // 一致性测试:Store/Load 比较(原骨架)
            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
                float64x2_t orig = vld1q_f64(vals + v * NEON_VECTOR_SIZE);
                vst1q_f64(store_buf + v * NEON_VECTOR_SIZE, orig);
            }
            for (int v = 0; v < VECTORS_PER_BLOCK; ++v) {
                float64x2_t orig = vld1q_f64(vals + v * NEON_VECTOR_SIZE);
                float64x2_t reload = vld1q_f64(store_buf + v * NEON_VECTOR_SIZE);
                uint64x2_t cmp = vceqq_u64(vreinterpretq_u64_f64(orig),
                                           vreinterpretq_u64_f64(reload));
                if (!(vgetq_lane_u64(cmp, 0) == 0xFFFFFFFFFFFFFFFFULL &&
                      vgetq_lane_u64(cmp, 1) == 0xFFFFFFFFFFFFFFFFULL)) {
                    consistent = false;
                    break;
                }
            }
            if (!consistent) break;
        }

        uint64_t expected_sum_bits = td->global_sum.load(std::memory_order_seq_cst);
        double expected_sum;
        memcpy(&expected_sum, &expected_sum_bits, 8);
        bool sum_ok = (read_sum == expected_sum);   // 双侧精确,顺序无关
        bool passed = sum_ok && consistent;

        if (!passed) {
            log_warning("mesh_upi_avx512_symm_f64: thread %d read_sum=%a "
                        "expected=%a consistent=%d", id, read_sum,
                        expected_sum, (int)consistent);
            report_fail_msg("mesh_upi_avx512_symm_f64: cross-core FP sum "
                            "mismatch or consistency failure");
            return EXIT_FAILURE;
        }

        td->read_done.fetch_add(1, std::memory_order_seq_cst);

        // ---------- 重置阶段(最后一个读完成者执行) ----------
        uint32_t expected_lock = 0;
        if (td->reset_lock.compare_exchange_strong(expected_lock, 1,
                                                   std::memory_order_seq_cst,
                                                   std::memory_order_seq_cst)) {
            while (td->read_done.load(std::memory_order_seq_cst) < total &&
                   test_time_condition(test)) {
                __asm__ volatile("yield");
            }
            if (!test_time_condition(test)) {
                td->reset_lock.store(0, std::memory_order_seq_cst);
                break;
            }
            td->global_sum.store(0, std::memory_order_seq_cst);
            td->next_block.store(0, std::memory_order_seq_cst);
            td->write_done.store(0, std::memory_order_seq_cst);
            td->read_done.store(0, std::memory_order_seq_cst);
            td->reset_lock.store(0, std::memory_order_seq_cst);
        } else {
            while (td->reset_lock.load(std::memory_order_seq_cst) != 0 &&
                   test_time_condition(test)) {
                __asm__ volatile("yield");
            }
            if (!test_time_condition(test)) break;
        }

    } while (test_time_condition(test));

    return EXIT_SUCCESS;
}

static int mesh_upi_avx512_symm_f64_finish(struct test *test) {
    auto *td = static_cast<TestData *>(test->data);
    free(td->data);
    delete td;
    return EXIT_SUCCESS;
}

#else
static int mesh_upi_avx512_symm_f64_init(struct test *test) {
    (void)test;
    log_skip(CpuNotSupportedSkipCategory,
             "to be implemented (placeholder): ARM NEON required for "
             "mesh_upi_avx512_symm_f64");
    return EXIT_SKIP;
}
static int mesh_upi_avx512_symm_f64_run(struct test *test, int cpu) { (void)test; (void)cpu; return EXIT_SKIP; }
static int mesh_upi_avx512_symm_f64_finish(struct test *test) { (void)test; return EXIT_SUCCESS; }
#endif
DECLARE_TEST(mesh_upi_avx512_symm_f64,
             "Cross-core shared-data f64 production/consumption (symm): "
             "the first FP mesh variant — NEON vfmaq_f64 chains on both "
